const weights = [leftWeight, focusWeight, rightWeight];
const total = weights.reduce((sum, w) => sum + w, 0);
const ticket = random() * total;
let zone = 0;
let edge = weights[0];
while (ticket >= edge && zone < weights.length - 1) {
  zone++;
  edge += weights[zone];
}
const x = (zone + random()) / 3 * canvas.width;
const y = random() * canvas.height;
drawPoint(x, y);
